// 1. Capturar variables del nodo trigger de forma segura
const inputData = $('When Executed by Another Workflow').item.json;
const callbackData = String(inputData.data || inputData.callback_query?.data || '');
const chatId = inputData.chatId || inputData.chat_id || inputData.callback_query?.message?.chat?.id || '000000';

// 2. Extraer el ID del producto (soporta formatos: "p_id=P001" o "confirmar_P001")
let prodId = 'P001';
if (callbackData.includes('=')) {
  prodId = callbackData.split('=')[1] || 'P001';
} else if (callbackData.includes('_')) {
  prodId = callbackData.split('_')[1] || 'P001';
} else {
  prodId = callbackData;
}

// 3. Cantidad por defecto para el primer clic
const qty = 1;

// 4. Generar ID único de pedido (PED-XXXXXX)
const timestamp = Date.now().toString().slice(-5);
const random = Math.floor(Math.random() * 90 + 10);
const idPedido = `PED-${timestamp}${random}`;

return {
  json: {
    chat_id: chatId,
    id_pedido: idPedido,
    prod_id: prodId,
    cantidad: qty,
    fecha: new Date().toISOString()
  }
};

// 1. Datos recibidos de Procesar Pedido e ID
const pedido = $('Procesar Pedido e ID').item.json;

// 2. Buscamos el producto coincidente en Leer Stock Actual
const productos = $('Leer Stock Actual').all().map(item => item.json);
const productoEncontrado = productos.find(p => String(p.id_producto) === String(pedido.prod_id)) || {};

// 3. Obtenemos datos del producto
const nombreProducto = productoEncontrado.nombre || 'Producto Desconocido';
const precioUnitario = Number(productoEncontrado.precio || 0);
const stockActual = Number(productoEncontrado.stock || 0);
const disponible = String(productoEncontrado.disponible || 'NO').trim().toUpperCase();

// 4. Cálculos
const cantidad = Number(pedido.cantidad || 1);
const stockNuevo = stockActual - cantidad;
const total = cantidad * precioUnitario;

return {
  json: {
    chat_id: pedido.chat_id,
    id_pedido: pedido.id_pedido,
    prod_id: pedido.prod_id,
    nombre: nombreProducto,
    precio: precioUnitario,
    cantidad: cantidad,
    total: total,
    fecha: pedido.fecha,
    stock_anterior: stockActual,
    stock_nuevo: stockNuevo,
    disponible: disponible
  }
};

// 1. Obtenemos lo que devolvió la búsqueda en Google Sheets
const filasSheets = $input.all();
const primerRegistro = filasSheets[0]?.json || {};

// 2. Obtenemos la información del nuevo producto recién seleccionado
const itemNuevo = $('Calcular Nuevo Stock').first().json;

const chatId = itemNuevo.chat_id || itemNuevo.chatId || primerRegistro.chat_id;
const nomNuevo = itemNuevo.nombre || 'Producto';
const cantNueva = Number(itemNuevo.cantidad || 1);
const subNuevo = Number(itemNuevo.total || (cantNueva * Number(itemNuevo.precio || 0)));

// 3. Leemos lo que ya tenía guardado en la columna "detalle" y "total"
let detalleExistente = primerRegistro.detalle || '';
let totalExistente = Number(primerRegistro.total || 0);

let detalleFinal = '';
let totalFinal = 0;

if (detalleExistente && String(detalleExistente).trim() !== '') {
  // Si ya existía un pedido, concatenamos en una línea nueva
  detalleFinal = `${detalleExistente}\n• ${cantNueva}x ${nomNuevo} ($${subNuevo})`;
  totalFinal = totalExistente + subNuevo;
} else {
  // Si es el primer producto del carrito
  detalleFinal = `• ${cantNueva}x ${nomNuevo} ($${subNuevo})`;
  totalFinal = subNuevo;
}

return {
  json: {
    chat_id: chatId,
    detalle: detalleFinal,
    total: totalFinal,
    estado: 'borrador'
  }
};

