const detalleTexto = filaCarrito.detalle || 'Sin detalle de productos';
const totalPagar = Number(filaCarrito.total || 0);

// Generamos un ID de pedido único
const idPedido = "PED-" + Math.floor(100000 + Math.random() * 900000);

// Convertimos el texto de la columna 'detalle' a formato HTML (cambiando saltos de línea por <br>)
const detalleHTML = String(detalleTexto).replace(/\n/g, '<br>');

return {
  json: {
    chat_id: chatId,
    id_pedido: idPedido,
    detalle_html: detalleHTML,
    detalle_texto: detalleTexto,
    total: totalPagar,
    fecha: new Date().toISOString()
  }
};

