const originalData = String($('When Executed by Another Workflow').item.json.data || '').trim();
const chatId = $('When Executed by Another Workflow').item.json.chatId;

// Si por error entra un comando en lugar de una categoría real, no buscamos nada
if (originalData.startsWith('action=') || originalData.startsWith('p_id=')) {
  return { json: { chat_id: chatId, texto: "Por favor selecciona una opción válida del menú.", reply_markup: JSON.stringify({ inline_keyboard: [] }) } };
}

const cat = originalData;
const todosLosProductos = $input.all().map(item => item.json);

const productosFiltrados = todosLosProductos.filter(p => 
  p.categoria && String(p.categoria).trim().toLowerCase() === cat.toLowerCase()
);

const botones = productosFiltrados.map(p => ([{
  text: `${p.nombre} - $${p.precio}`,
  callback_data: `p_id=${p.id_producto}`
}]));

// Botón para regresar al menú principal
botones.push([{ text: '⬅️ Volver al Menú', callback_data: 'action=menu' }]);

return {
  json: {
    chat_id: chatId,
    texto: productosFiltrados.length
      ? `📋 *Productos en ${cat.toUpperCase()}:*\nElige uno para continuar 👇`
      : `😕 No hay productos disponibles en *${cat}* por ahora.`,
    reply_markup: JSON.stringify({ inline_keyboard: botones })
  }
};
